files.content:
[hidden] {
  display: none !important;
}

:root {
  --bg-color: #2b2b36;
  --card-bg: #1c1c24;
  --primary: #ffd166;
  --text-main: #f4f4f9;
  --text-dim: #9aa0a6;
  --clue-bg: #2d2f3f;
  --editable-bg: #13141a;
  --error-bg: #ff5252;
  --error-text: #ffffff;
  --success-color: #06d6a0;
  --border-color: #4a4e69;
  --thick-border: #ffd166;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: "Courier New", Courier, monospace, system-ui, sans-serif;
  font-size: 16px;
  background-color: var(--bg-color);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-container {
  background: var(--card-bg);
  border: 4px solid var(--border-color);
  box-shadow: 6px 6px 0px #0e0e13;
  width: 100%;
  max-width: 440px;
  padding: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

.game-header {
  text-align: center;
}

.game-title {
  font-size: 1.5rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--primary);
  margin-bottom: 8px;
  text-shadow: 2px 2px 0px #000;
}

.game-desc {
  font-size: 0.95rem;
  color: var(--text-dim);
  line-height: 1.4;
}

.board-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}

.solved-banner {
  width: 100%;
  text-align: center;
  background-color: var(--success-color);
  color: #0d3b2e;
  font-weight: bold;
  font-size: 1.3rem;
  padding: 10px;
  margin-bottom: 16px;
  border: 3px solid #049f76;
  box-shadow: 3px 3px 0px #000;
  text-transform: uppercase;
  letter-spacing: 2px;
  animation: popIn 0.25s ease-out;
}

@keyframes popIn {
  0% { transform: scale(0.9); opacity: 0; }
  100% { transform: scale(1); opacity: 1; }
}

.grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-template-rows: repeat(4, 1fr);
  gap: 2px;
  background-color: var(--thick-border);
  border: 4px solid var(--thick-border);
  box-shadow: 4px 4px 0px #000;
  width: 100%;
  max-width: 320px;
  aspect-ratio: 1 / 1;
}

.cell {
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  background: var(--editable-bg);
}

/* 2x2 Box Separation Boundaries */
.cell:nth-child(4n + 2) {
  margin-right: 2px;
}
.cell:nth-child(n + 5):nth-child(-n + 8) {
  margin-bottom: 2px;
}

.cell input {
  width: 100%;
  height: 100%;
  background: transparent;
  border: none;
  text-align: center;
  font-size: 1.75rem;
  font-family: inherit;
  font-weight: bold;
  color: var(--primary);
  outline: none;
  cursor: text;
  caret-color: var(--primary);
}

.cell input:focus {
  background: #252839;
  box-shadow: inset 0 0 0 2px var(--primary);
}

.cell.clue input {
  background: var(--clue-bg);
  color: #ffffff;
  cursor: not-allowed;
  user-select: none;
}

.cell.conflict input {
  background-color: var(--error-bg) !important;
  color: var(--error-text) !important;
}

.controls {
  display: flex;
  gap: 12px;
  width: 100%;
  justify-content: center;
}

.btn {
  flex: 1;
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  padding: 10px 16px;
  border: 3px solid #000;
  background-color: var(--primary);
  color: #111;
  cursor: pointer;
  box-shadow: 3px 3px 0px #000;
  transition: transform 0.1s, box-shadow 0.1s;
}

.btn:hover {
  transform: translate(-1px, -1px);
  box-shadow: 4px 4px 0px #000;
}

.btn:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0px #000;
}

.btn:focus-visible {
  outline: 2px dashed #ffffff;
  outline-offset: 2px;
}

.btn-secondary {
  background-color: #4a4e69;
  color: #ffffff;
}

@media (max-width: 360px) {
  .game-container {
    padding: 16px;
  }
  .grid {
    max-width: 260px;
  }
  .cell input {
    font-size: 1.4rem;
  }
  .btn {
    font-size: 0.9rem;
    padding: 8px 10px;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  // Built-in 4x4 Sudoku Puzzle (0 represents empty cells)
  // Solution:
  // 1 2 | 3 4
  // 3 4 | 1 2
  // ----+----
  // 2 1 | 4 3
  // 4 3 | 2 1
  const INITIAL_PUZZLE = [
    [1, 0, 0, 4],
    [0, 0, 1, 0],
    [0, 1, 0, 0],
    [4, 0, 0, 1]
  ];

  const gridElement = document.getElementById('sudokuGrid');
  const solvedBanner = document.getElementById('solvedBanner');
  const resetBtn = document.getElementById('resetBtn');
  const clearBtn = document.getElementById('clearBtn');

  const inputs = [];

  function createGrid() {
    gridElement.innerHTML = '';
    inputs.length = 0;

    for (let r = 0; r < 4; r++) {
      for (let c = 0; c < 4; c++) {
        const cell = document.createElement('div');
        cell.classList.add('cell');
        cell.setAttribute('role', 'gridcell');
        cell.dataset.row = r;
        cell.dataset.col = c;

        const input = document.createElement('input');
        input.type = 'text';
        input.inputMode = 'numeric';
        input.maxLength = 1;
        input.setAttribute('aria-label', `Row ${r + 1}, Column ${c + 1}`);

        const initialValue = INITIAL_PUZZLE[r][c];
        if (initialValue !== 0) {
          input.value = initialValue;
          input.readOnly = true;
          input.tabIndex = -1;
          cell.classList.add('clue');
        } else {
          input.value = '';
        }

        cell.appendChild(input);
        gridElement.appendChild(cell);
        inputs.push(input);

        input.addEventListener('keydown', (e) => handleNavigation(e, r, c));
        input.addEventListener('input', (e) => handleInput(e, input));
      }
    }
    validateGrid();
  }

  function handleInput(e, input) {
    const val = input.value;
    if (!/^[1-4]$/.test(val)) {
      input.value = '';
    }
    validateGrid();
  }

  function handleNavigation(e, r, c) {
    let nextR = r;
    let nextC = c;

    switch (e.key) {
      case 'ArrowUp':
        nextR = Math.max(0, r - 1);
        break;
      case 'ArrowDown':
        nextR = Math.min(3, r + 1);
        break;
      case 'ArrowLeft':
        nextC = Math.max(0, c - 1);
        break;
      case 'ArrowRight':
        nextC = Math.min(3, c + 1);
        break;
      case 'Backspace':
        if (!inputIsClue(r, c) && e.target.value === '') {
          // Allow natural backspacing
        }
        return;
      default:
        return;
    }

    e.preventDefault();
    focusCell(nextR, nextC);
  }

  function focusCell(r, c) {
    const idx = r * 4 + c;
    if (inputs[idx]) {
      inputs[idx].focus();
      inputs[idx].select();
    }
  }

  function inputIsClue(r, c) {
    return INITIAL_PUZZLE[r][c] !== 0;
  }

  function validateGrid() {
    const board = [];
    const cells = gridElement.querySelectorAll('.cell');

    // Clear previous conflicts
    cells.forEach((cell) => cell.classList.remove('conflict'));

    // Read board values
    for (let r = 0; r < 4; r++) {
      const rowVals = [];
      for (let c = 0; c < 4; c++) {
        const val = inputs[r * 4 + c].value;
        rowVals.push(val ? parseInt(val, 10) : 0);
      }
      board.push(rowVals);
    }

    const conflictingIndices = new Set();

    // Check rows
    for (let r = 0; r < 4; r++) {
      const seen = new Map();
      for (let c = 0; c < 4; c++) {
        const val = board[r][c];
        if (val !== 0) {
          if (seen.has(val)) {
            conflictingIndices.add(r * 4 + c);
            conflictingIndices.add(r * 4 + seen.get(val));
          } else {
            seen.set(val, c);
          }
        }
      }
    }

    // Check columns
    for (let c = 0; c < 4; c++) {
      const seen = new Map();
      for (let r = 0; r < 4; r++) {
        const val = board[r][c];
        if (val !== 0) {
          if (seen.has(val)) {
            conflictingIndices.add(r * 4 + c);
            conflictingIndices.add(seen.get(val) * 4 + c);
          } else {
            seen.set(val, r);
          }
        }
      }
    }

    // Check 2x2 boxes
    for (let boxRow = 0; boxRow < 2; boxRow++) {
      for (let boxCol = 0; boxCol < 2; boxCol++) {
        const seen = new Map();
        for (let r = 0; r < 2; r++) {
          for (let c = 0; c < 2; c++) {
            const currR = boxRow * 2 + r;
            const currC = boxCol * 2 + c;
            const val = board[currR][currC];
            if (val !== 0) {
              if (seen.has(val)) {
                conflictingIndices.add(currR * 4 + currC);
                conflictingIndices.add(seen.get(val));
              } else {
                seen.set(val, currR * 4 + currC);
              }
            }
          }
        }
      }
    }

    // Apply conflict classes
    conflictingIndices.forEach((index) => {
      cells[index].classList.add('conflict');
    });

    // Check win condition: complete and no conflicts
    let isFull = true;
    for (let r = 0; r < 4; r++) {
      for (let c = 0; c < 4; c++) {
        if (board[r][c] === 0) {
          isFull = false;
          break;
        }
      }
    }

    if (isFull && conflictingIndices.size === 0) {
      solvedBanner.removeAttribute('hidden');
    } else {
      solvedBanner.setAttribute('hidden', '');
    }
  }

  resetBtn.addEventListener('click', () => {
    createGrid();
  });

  clearBtn.addEventListener('click', () => {
    for (let r = 0; r < 4; r++) {
      for (let c = 0; c < 4; c++) {
        if (!inputIsClue(r, c)) {
          inputs[r * 4 + c].value = '';
        }
      }
    }
    validateGrid();
  });

  createGrid();
});
